export function binarySearch(xs, x) {
  let lo = 0, hi = xs.length - 1
  while (lo <= hi) {
    const mid = (lo + hi) >> 1
    if (xs[mid] === x) return mid
    if (xs[mid] < x) lo = mid + 1
    else hi = mid - 1
  }
  return -1
}
